python3 << 'PYEOF'
import os
import re
from collections import defaultdict

REPO = "/bench/repo"
MODULE = "github.com/usememos/memos"

# Data layer: store tree + proto/store source + proto/gen/store generated
def is_data_layer(path):
    rel = path.replace(REPO + "/", "")
    if rel.startswith("store/"):
        return True
    if rel.startswith("proto/store/"):
        return True
    if rel.startswith("proto/gen/store/"):
        return True
    return False

def go_package_path(filepath):
    """Return import path for a Go file."""
    rel = filepath.replace(REPO + "/", "")
    dirpath = os.path.dirname(rel)
    if not dirpath:
        return MODULE
    return f"{MODULE}/{dirpath}"

def get_package_name(filepath):
    try:
        with open(filepath) as f:
            for line in f:
                m = re.match(r'^package\s+(\w+)', line)
                if m:
                    return m.group(1)
    except:
        pass
    return None

# Core persistent entity types from store/*.go (map to DB tables)
GO_ENTITIES = [
    "User", "UserSetting", "UserIdentity",
    "Memo", "MemoRelation", "MemoShare",
    "Attachment", "IdentityProvider", "Inbox", "Reaction",
    "InstanceSetting", "AuthenticationConfigState",
]

# Proto persistent entity/payload types from proto/store
PROTO_ENTITIES = [
    "MemoPayload", "AttachmentPayload",
    "IdentityProvider", "IdentityProviderConfig",
    "InboxMessage", "InstanceSetting",
    "UserSetting", "GeneralUserSetting",
    "RefreshTokensUserSetting", "PersonalAccessTokensUserSetting",
    "InstanceBasicSetting", "InstanceGeneralSetting",
    "InstanceStorageSetting", "InstanceMemoRelatedSetting",
    "InstanceTagsSetting", "InstanceNotificationSetting", "InstanceAISetting",
]

# Collect all Go files outside data layer
external_files = []
for root, dirs, files in os.walk(REPO):
    if "/.git" in root:
        continue
    for fn in files:
        if fn.endswith(".go"):
            fp = os.path.join(root, fn)
            if not is_data_layer(fp):
                external_files.append(fp)

print(f"External Go files: {len(external_files)}")

# For each entity, find referencing packages
def count_entity_refs(entity_name, patterns):
    """Count distinct external packages referencing entity."""
    pkg_files = defaultdict(list)
    for fp in external_files:
