  'InstanceBasicSetting', 'InstanceGeneralSetting',
  'InstanceStorageSetting', 'InstanceMemoRelatedSetting',
  'InstanceTagsSetting', 'InstanceNotificationSetting', 'InstanceAISetting',
];

