perl - << 'PERL'
use strict;
use warnings;
use File::Find;
use File::Basename;

my $repo = '/bench/repo';
my $module = 'github.com/usememos/memos';

sub is_data_layer {
    my ($rel) = @_;
    return 1 if $rel =~ m{^store/};
    return 1 if $rel =~ m{^proto/store/};
    return 1 if $rel =~ m{^proto/gen/store/};
    return 0;
}

sub go_pkg_path {
    my ($rel) = @_;
    my $dir = dirname($rel);
    return $dir eq '.' ? $module : "$module/$dir";
}

my @external;
find(sub {
    return if $_ eq '.git';
    return unless -f && /\.go$/;
    my $full = $File::Find::name;
    my $rel = substr($full, length($repo)+1);
    push @external, $full unless is_data_layer($rel);
}, $repo);

my @go_entities = qw(User UserSetting UserIdentity Memo MemoRelation MemoShare Attachment IdentityProvider Inbox Reaction InstanceSetting AuthenticationConfigState);
my @proto_entities = qw(MemoPayload AttachmentPayload IdentityProvider IdentityProviderConfig InboxMessage InstanceSetting UserSetting GeneralUserSetting RefreshTokensUserSetting PersonalAccessTokensUserSetting InstanceBasicSetting InstanceGeneralSetting InstanceStorageSetting InstanceMemoRelatedSetting InstanceTagsSetting InstanceNotificationSetting InstanceAISetting);

sub count_refs {
    my ($files_ref, $entity, $prefix) = @_;
    my @patterns = (
        qr/\b\Q$prefix\E\.\Q$entity\E\b/,
        qr/\*\Q$prefix\E\.\Q$entity\E\b/,
        qr/\[\]\*\Q$prefix\E\.\Q$entity\E\b/,
        qr/\[\]\Q$prefix\E\.\Q$entity\E\b/,
        qr/\b\Q$prefix\E\.\Q$entity\E\{/,
    );
    my %pkgs;
    for my $fp (@$files_ref) {
        open my $fh, '<', $fp or next;
        local $/; my $content = <$fh>; close $fh;
        my $matched = 0;
        for my $p (@patterns) {
            if ($content =~ $p) { $matched = 1; last; }
        }
        next unless $matched;
        my $rel = substr($fp, length($repo)+1);
        my $pkg = go_pkg_path($rel);
        push @{$pkgs{$pkg}}, $rel;
    }
    return \%pkgs;
}

my @results;
for my $e (@go_entities) {
    my $pkgs = count_refs(\@external, $e, 'store');
    push @results, { name => "store.$e", count => scalar keys %$pkgs, pkgs => $pkgs };
}
for my $e (@proto_entities) {
    my $pkgs = count_refs(\@external, $e, 'storepb');
    push @results, { name => "storepb.$e", count => scalar keys %$pkgs, pkgs => $pkgs };
}

@results = sort { $b->{count} <=> $a->{count} } @results;

print "External Go files: ", scalar(@external), "\n\n";
print "=== TOP 20 ===\n";
my $top = 0;
for my $r (@results) {
    last unless $r->{count} > 0;
    printf "%3d  %s\n", $r->{count}, $r->{name};
    my @keys = sort keys %{$r->{pkgs}};
    my $limit = @keys > 12 ? 12 : @keys;
    for my $k (@keys[0..$limit-1]) {
        print "      $k\n";
    }
    print "      ... +", scalar(@keys)-12, " more\n" if @keys > 12;
    last if ++$top >= 20;
}

print "\n=== ALL GO ENTITIES ===\n";
for my $e (@go_entities) {
    my $pkgs = count_refs(\@external, $e, 'store');
    printf "%3d  store.%s\n", scalar keys %$pkgs, $e;
}

print "\n=== ALL PROTO ENTITIES (nonzero) ===\n";
for my $r (@results) {
    next unless $r->{name} =~ /^storepb\./;
    next unless $r->{count} > 0;
    printf "%3d  %s\n", $r->{count}, $r->{name};
}
PERL

